      if (off + 16 > bit_len) {
        out->outcome = 1;
        out->reason = PK_R_OUT_OF_BOUNDS;
        out->consumed_bits = off;
        return 1;
      }
      out->fabric_header_cpu.reason_code = (uint16_t)(((uint64_t)buf[((off >> 3) + 0) & PK_BUF_MASK] << 8) | (uint64_t)buf[((off >> 3) + 1) & PK_BUF_MASK]);
